## 📜 脚本代码

```python
import requests
import json
import sys

def introspect_graphql(url, headers=None, timeout=10):
    query = """
    query {
      __schema {
        types {
          name
          kind
          description
          fields {
            name
            description
            args {
              name
              description
              type {
                name
                kind
              }
            }
          }
          interfaces {
            name
          }
          enumValues {
            name
            description
          }
          inputFields {
            name
            description
            type {
              name
              kind
            }
          }
        }
      }
    }
    """

    try:
        response = requests.post(url, json={'query': query}, headers=headers, timeout=timeout)
        response.raise_for_status()
        data = response.json()
        return data.get('data', {}).get('__schema', {})
    except requests.exceptions.RequestException as e:
        print(f"Error during introspection: {e}")
        return {}

def save_schema_to_file(schema, filename='schema.json'):
    with open(filename, 'w') as f:
        json.dump(schema, f, indent=2)
    print(f"Schema saved to {filename}")

def main():
    if len(sys.argv) < 2:
        print("Usage: python introspect_graphql.py <GRAPHQL_URL> [headers]")
        print("Example: python introspect_graphql.py http://example.com/graphql")
        sys.exit(1)

    url = sys.argv[1]
    headers = {}
    if len(sys.argv) > 2:
        headers = json.loads(sys.argv[2])

    schema = introspect_graphql(url, headers=headers)
    if schema:
        print("GraphQL Schema extracted successfully:")
        print(json.dumps(schema, indent=2))
        save_schema_to_file(schema)
    else:
        print("Failed to extract GraphQL schema.")

if __name__ == '__main__':
    main()
```

