## 三、代码示例（C++）

以下是一个简单的示例，演示如何通过`NtOpenProcess`直接调用内核态系统调用，避免用户态Hook检测。

```cpp
#include <windows.h>
#include <winternl.h>
#include <iostream>

// 获取NtOpenProcess函数地址
typedef NTSTATUS(WINAPI* NTOPENPROCESS)(
    PHANDLE ProcessHandle,
    ACCESS_MASK DesiredAccess,
    POBJECT_ATTRIBUTES ObjectAttributes
);

int main() {
    // 获取Ntdll.dll的句柄
    HMODULE hNtdll = GetModuleHandle(L"ntdll.dll");
    if (!hNtdll) {
        std::cerr << "Failed to get ntdll.dll handle." << std::endl;
        return 1;
    }

    // 获取NtOpenProcess函数地址
    NTOPENPROCESS NtOpenProcess = (NTOPENPROCESS)GetProcAddress(hNtdll, "NtOpenProcess");
    if (!NtOpenProcess) {
        std::cerr << "Failed to get NtOpenProcess address." << std::endl;
        return 1;
    }

    // 构造参数
    HANDLE hProcess = NULL;
    ACCESS_MASK DesiredAccess = PROCESS_ALL_ACCESS;
    OBJECT_ATTRIBUTES ObjectAttributes = { 0 };
    ObjectAttributes.Length = sizeof(OBJECT_ATTRIBUTES);
    ObjectAttributes.ObjectName = NULL;
    ObjectAttributes.Attributes = OBJ_CASE_INSENSITIVE;
    ObjectAttributes.SecurityDescriptor = NULL;
    ObjectAttributes.SecurityQualityOfService = NULL;

    // 调用NtOpenProcess（直接内核态调用）
    NTSTATUS status = NtOpenProcess(&hProcess, DesiredAccess, &ObjectAttributes);

    if (NT_SUCCESS(status)) {
        std::cout << "Process opened successfully: " << hProcess << std::endl;
        // 可以进行后续操作，如读写内存、注入代码等
    } else {
        std::cerr << "Failed to open process. Status: " << status << std::endl;
    }

    return 0;
}
```

