// 假设我们有一个任务队列
const taskQueue = [];

// 分发任务
function distributeTask(task) {
    const availableClients = Array.from(clients.values()).filter(client => client.readyState === WebSocket.OPEN);
    if (availableClients.length === 0) {
        console.log('No available clients to distribute task');
        return;
    }

    const client = availableClients[0];
    client.send(JSON.stringify(task));
    console.log('Task sent to client');
}

